import { cookies } from "next/headers";
import ProfileClient from "./ProfileClient";
import { redirect } from "next/navigation";
import { jwtVerify } from "jose";
import { db } from "@/src/prisma/db";

export default async function ProfilePage() {
    const token = (await cookies()).get("token")?.value;
    if(!token) redirect("/login");
    let currentUserId: string
    try {
        const { payload } = await jwtVerify(token, new TextEncoder().encode(process.env.SECRET_KEY));
        currentUserId = String(payload.id);   
    } catch (error) {
        redirect("/login");
    }
    const currentUser = await db.orm.public.Users.where({ id: String(currentUserId) }).select("id","email","phone","role","username","createdAt", "updatedAt").first();
    if(!currentUser) return redirect("/login")
    return<ProfileClient user={currentUser}/>
}